import { cookies } from 'next/headers'

// Stand-in for a real database. Swap these two functions for your own
// persistence layer; the Server Action and page don't need to change.
const notificationsByUser = new Map<string, boolean>()

async function getUserId() {
  const cookieStore = await cookies()
  const userId = cookieStore.get('userId')?.value

  if (!userId) {
    throw new Error('Unauthorized')
  }

  return userId
}

export async function getNotificationsEnabled() {
  const userId = await getUserId()
  return notificationsByUser.get(userId) ?? false
}

export async function setNotificationsEnabled(enabled: boolean) {
  const userId = await getUserId()
  notificationsByUser.set(userId, enabled)
  return enabled
}

