import { toggleNotifications } from '@/app/actions'
import { getNotificationsEnabled } from '@/app/lib/preferences'

export default async function Home() {
  const enabled = await getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">Turn {enabled ? 'off' : 'on'}</button>
      </form>
    </main>
  )
}

